          '**El G98 es una notificación, no una solicitud: conectas primero y se lo comunicas después a tu Distribution Network Operator, en un plazo de 28 días desde la conexión.** Es gratuito, cubre todos los generadores de hasta 3.68 kW por fase y la mayoría de DNO aceptan un formulario en línea. Guarda la confirmación.',
          '**No te lo saltes porque no haya intervenido un electricista.** Un kit enchufable sigue siendo generación conectada a la red pública, y la notificación es lo que mantiene al día los registros de capacidad local de tu DNO. En Irlanda del Norte el equivalente es el G98/NI, que se notifica a NIE Networks en 30 días.',
          'Las normas de red G98 actuales limitan cada vivienda a un dispositivo enchufable. **Elige el kit de 890 W en lugar de dos de 460 W** si quieres más producción: una segunda unidad no es una vía admitida en la situación actual, aunque el margen de paneles lo permitiría.',
