          '**O SI 2026/848 é o instrumento que tornou a solar plug-in legal na Grã-Bretanha, não a BS 7671 Amendment 4.** O ato normativo foi editado em 16 de julho de 2026 e entrou em vigor em 27 de agosto de 2026, alterando o Plugs and Sockets etc. (Safety) Regulations 1994 e o Electricity Safety, Quality and Continuity Regulations 2002 para criar uma via de venda e uso de microgeradores plug-in qualificados.',
