          'Module dürfen nicht an Balkonen, Zäunen, Wänden oder Toren aus Holz montiert werden – eine Brandschutzauflage, die einen großen Teil der britischen Balkone ausschließt, noch bevor es um die Zustimmung des Vermieters geht.',
