      faqSection: {
        id: 'faq',
        title: 'Häufig gestellte Fragen',
        faqs: [
          { q: 'Ist Steckersolar auf dem Balkon in Großbritannien seit dem 27. August 2026 legal?', a: 'Ja, in Großbritannien. Das SI 2026/848 trat am 27. August 2026 in Kraft und schuf einen legalen Weg, komplette Steckersolar-Sets nach der DESNZ Interim Product Specification v2 zu verkaufen und zu nutzen. Nordirland ist ein eigenes Regime mit eigenen Anschlussregeln.' },
          { q: 'Brauche ich einen Elektriker für die Installation eines Steckersolar-Sets?', a: 'Nein, sofern das Set ein werkseitig komplettes Produkt mit dem Status Compliant im ENA-Typprüfregister ist. Alles andere – lose Komponenten, ein selbst zusammengestelltes System oder ein Set mit Batterie – erfordert weiterhin einen CPS-registrierten Elektriker und einen Festanschluss.' },
          { q: 'Wie viel kann ich tatsächlich sparen?', a: 'Die amtliche Schätzung liegt bei bis zu 110 £ pro Jahr und deckt rund 20 % des Stromverbrauchs eines durchschnittlichen Haushalts ab, Branchenzahlen beginnen bei 70 £. Diese Spanne unterstellte ein Set für 400–600 £, bei Startpreisen von 699–965 £ ist die Amortisationszeit also länger, als die Schlagzeile vermuten lässt.' },
          { q: 'Darf ich ein Steckersolar-Modul an einem Holzbalkon anbringen?', a: 'Nein. Module dürfen wegen der Brandschutzauflage nicht an Balkonen, Zäunen, Wänden oder Toren aus Holz montiert werden. Ein ballastiertes Set, das auf dem Balkonboden steht, ist der übliche Ausweg, da nichts am Holz befestigt wird.' },
          { q: 'Was ist die G98-Meldung und wann reiche ich sie ein?', a: 'G98 ist eine kostenlose Meldung an Ihren Distribution Network Operator, dass Sie einen kleinen Erzeuger angeschlossen haben. Sie installieren zuerst und melden innerhalb von 28 Tagen nach dem Anschluss; es ist keine Genehmigung, auf die Sie warten müssen. Nordirland nutzt das G98/NI mit einer Frist von 30 Tagen.' },
          { q: 'Kann ich einem Steckersolar-Set eine Batterie hinzufügen?', a: 'Auf diesem Weg nicht. Das SI 2026/848 schließt Batterien, Sets mit integriertem Speicher und tragbare Powerstations aus, die in die Hausinstallation einspeisen. Eine Anlage mit Batterie bleibt zulässig, aber über den Weg des Festanschlusses mit Elektriker, nicht als steckerfertiges Gerät.' },
          { q: 'Wie viele Steckersolar-Sets darf ich haben?', a: 'Eines pro Haushalt nach der aktuellen G98-Netzposition. Wenn Sie mehr Ertrag wollen, wählen Sie ein einzelnes Set mit höherer Leistung, etwa ein Modell mit 890 W oder 920 W, statt zwei kleinere Einheiten zu installieren.' },
          { q: 'Welche Sets waren zum Zeitpunkt der Gesetzesänderung tatsächlich zertifiziert?', a: 'Vier UKSOL-Sets – Pro Compact 460 W mit Bodenaufständerung, Pro Compact 515 W Hybrid, Pro Duo 890 W Hybrid und Pro Advanced 920 W Hybrid – wurden am 18. und 19. August 2026 als Compliant registriert. Die Anträge für die Anker Solarbank 4 Pro und HDM Solars PIS0100 standen beide noch auf Non-compliant.' },
          { q: 'Hat Großbritannien Balkonsolar nicht schon im April 2026 legalisiert?', a: 'Im April 2026 kam BS 7671 Amendment 4, das Abschnitt 712 der Verdrahtungsvorschriften aktualisierte. Es erlaubte für sich allein nicht, einen Erzeuger an eine normale 13-A-Steckdose anzuschließen. Das SI 2026/848 vom August ist die Änderung, die das bewirkt hat.' },
        ],
      },
